const FontSize& font_size(int size) {
    static const FontSize sizes[] = {
        {1, 7, 2, 11, S1_GLYPHS, S1_BITS},   // 10 px
        {2, 10, 3, 16, S2_GLYPHS, S2_BITS},   // 14 px
        {3, 15, 4, 24, S3_GLYPHS, S3_BITS},   // 20 px
    };
    return sizes[size <= 1 ? 0 : size >= 3 ? 2 : 1];
}

